import{_ as p,a0 as o,w as d,s as r,ao as l,I as t,x as i,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"改變我使用 Git 工作方式的七個技巧 | LCTT x X-CMD","titleTemplate":false,"description":"改變我使用 Git 工作方式的七個技巧 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"改變我使用 Git 工作方式的七個技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"改變我使用 Git 工作方式的七個技巧 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201026 7 Git tricks that changed my life","title":"改變我使用 Git 工作方式的七個技巧","tag":"202012","desc":""},"relativePath":"202012/20201026 7 Git tricks that changed my life.md","filePath":"[post].md"}'),g={name:"202012/20201026 7 Git tricks that changed my life.md"};function h(k,s,u,b,c,f){const a=o("Link");return d(),r("div",null,[s[36]||(s[36]=l(`<h1 id="改變我使用-git-工作方式的七個技巧" tabindex="-1">改變我使用 Git 工作方式的七個技巧 <a class="header-anchor" href="#改變我使用-git-工作方式的七個技巧" aria-label="Permalink to “改變我使用 Git 工作方式的七個技巧”">​</a></h1><blockquote><p>這些有用的技巧將改變你使用這個流行的版本控制系統的工作方式。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/07/092803d67fa7bttuuj98fb.jpg" alt=""></p><p>Git 是目前最常見的版本控制系統之一，無論是私有系統還是公開託管的網站，都在使用它進行各種開發工作。但無論我對 Git 的使用有多熟練，似乎總有一些功能還沒有被發現，下面是改變我使用 Git 工作方式的七個技巧。</p><h3 id="_1、git-中的自動更正" tabindex="-1">1、Git 中的自動更正 <a class="header-anchor" href="#_1、git-中的自動更正" aria-label="Permalink to “1、Git 中的自動更正”">​</a></h3><p>我們有時都會打錯字，但如果啓用了 Git 的自動更正功能，就可以讓 Git 自動修正打錯的子命令。</p><p>假設你想用 <code>git status</code> 檢查狀態，卻不小心輸入了 <code>git stats</code>。正常情況下，Git 會告訴你 <code>stats</code> 不是一條有效的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stats</span></span>
<span class="line"><span>git: ‘stats’ is not a git command. See ‘git --help’.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The most similar command is</span></span>
<span class="line"><span>status</span></span></code></pre></div><p>為了避免類似的情況發生，請在 Git 配置中啓用 Git 自動更正功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config --global help.autocorrect 1</span></span></code></pre></div><p>如果你希望這個命令只適用於你當前的版本庫，請省略 <code>--global</code> 選項。</p>`,11)),t("p",null,[s[1]||(s[1]=i("這條命令啓用了自動更正功能。更深入的教程可以在 ",-1)),e(a,{href:"https://git-scm.com/book/en/v2/Customizing-Git-Git-Configuration#_code_help_autocorrect_code"},{default:n(()=>[...s[0]||(s[0]=[i("Git Docs",-1)])]),_:1}),s[2]||(s[2]=i(" 中找到，但嘗試一下和上面一樣的錯誤命令，就能很好地瞭解這個配置的作用：",-1))]),s[37]||(s[37]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git stats</span></span>
<span class="line"><span>git: ‘stats’ is not a git command. See ‘git --help’.</span></span>
<span class="line"><span>On branch master</span></span>
<span class="line"><span>Your branch is up to date with ‘origin/master’.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nothing to commit, working tree clean</span></span></code></pre></div><p>Git 現在不會建議使用其他子命令，而是直接運行最上面的建議，在本例中是 <code>git status</code>。</p><h3 id="_2、計算你的提交量" tabindex="-1">2、計算你的提交量 <a class="header-anchor" href="#_2、計算你的提交量" aria-label="Permalink to “2、計算你的提交量”">​</a></h3><p>你需要計算提交數量可能有很多原因。例如，許多開發者通過計算提交數量來判斷何時該增加構建版本號，或者只是想了解項目的進展情況。</p><p>要計算提交數量其實很簡單直接，下面是 Git 的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list --count branch-name</span></span></code></pre></div><p>在上面的命令中，<code>branch-name</code> 應該是當前版本庫中有效的分支名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list –count master</span></span>
<span class="line"><span>32</span></span>
<span class="line"><span>$ git rev-list –count dev</span></span>
<span class="line"><span>34</span></span></code></pre></div><h3 id="_3、優化你的倉庫" tabindex="-1">3、優化你的倉庫 <a class="header-anchor" href="#_3、優化你的倉庫" aria-label="Permalink to “3、優化你的倉庫”">​</a></h3>`,9)),t("p",null,[s[4]||(s[4]=i("你的代碼倉庫不僅對你有價值，對你的組織也有價值。你可以通過一些簡單的做法來保持你的版本庫的清潔和更新。其中一個最好的做法是 ",-1)),e(a,{href:"https://linux.cn/article-12524-1.html"},{default:n(()=>[...s[3]||(s[3]=[i("使用 .gitignore 文件",-1)])]),_:1}),s[5]||(s[5]=i("。使用這個文件，就是告訴 Git 不要存儲許多不需要的文件，比如二進制文件、臨時文件等等。",-1))]),s[38]||(s[38]=l(`<p>為了進一步優化你的版本庫，你可以使用 Git 的垃圾收集功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git gc --prune=now --aggressive</span></span></code></pre></div><p>當你或你的團隊大量使用 <code>pull</code> 或 <code>push</code> 命令時，這條命令就會起到幫助作用。</p><p>這個命令是一個內部工具，可以清理倉庫中無法訪問或 “孤兒” Git 對象。</p><h3 id="_4、備份未被跟蹤的文件" tabindex="-1">4、備份未被跟蹤的文件 <a class="header-anchor" href="#_4、備份未被跟蹤的文件" aria-label="Permalink to “4、備份未被跟蹤的文件”">​</a></h3><p>大多數時候，刪除所有未被跟蹤的文件是安全的。不過很多時候，你不僅要刪除，還要為你的未跟蹤文件創建一個備份，以備以後需要。</p><p>通過 Git 和一些 Bash 命令管道，可以很容易地為你的未被跟蹤的文件創建一個壓縮包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git ls-files --others --exclude-standard -z |\\</span></span>
<span class="line"><span>xargs -0 tar rvf ~/backup-untracked.zip</span></span></code></pre></div><p>上面的命令製作了一個名為 <code>backup-untracked.zip</code> 的存檔（並排除了 <code>.gitignore</code> 中列出的文件）。</p><h3 id="_5、瞭解你的-git-文件夾" tabindex="-1">5、瞭解你的 .git 文件夾 <a class="header-anchor" href="#_5、瞭解你的-git-文件夾" aria-label="Permalink to “5、瞭解你的 .git 文件夾”">​</a></h3><p>每個版本庫都有一個 <code>.git</code> 文件夾。它是一個特殊的隱藏文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -a</span></span>
<span class="line"><span>. … .git</span></span></code></pre></div><p>Git 的工作主要依賴於兩個部分：</p><ol><li>工作樹（你當前簽出的文件狀態）。</li><li>你的 Git 倉庫的路徑（即你的 <code>.git</code> 文件夾的位置，其中包含版本信息）。</li></ol><p>這個文件夾存儲了所有的引用和其他重要的細節，比如配置、倉庫數據、HEAD 狀態、日誌等等。</p><p>如果你刪除這個文件夾，你的源代碼的當前狀態不會被刪除，但你的遠程信息，如你的項目歷史記錄，會被刪除。刪除這個文件夾意味着你的項目（至少是本地副本）不再處於版本控制之下。這意味着你不能跟蹤你的變化；你不能從遠程拉取或推送。</p><p>一般來説，不需要在 <code>.git</code> 文件夾裏做什麼，也沒有什麼應該做的。它是由 Git 管理的，基本上被認為是個禁區。然而，這個目錄裏有一些有趣的工件，包括 HEAD 的當前狀態。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat .git/HEAD</span></span>
<span class="line"><span>ref: refs/heads/master</span></span></code></pre></div><p>它還可能包含對你的存儲庫的描述：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat .git/description</span></span></code></pre></div><p>這是一個未命名的倉庫，編輯這個 <code>description</code> 文件可以命名這個倉庫。</p>`,21)),t("p",null,[s[7]||(s[7]=i("Git 鈎子文件夾（",-1)),s[8]||(s[8]=t("code",null,"hooks",-1)),s[9]||(s[9]=i("）也在這裏，裏面有一些鈎子示例文件。你可以閲讀這些示例來了解通過 Git 鈎子可以實現什麼，你也可以 ",-1)),e(a,{href:"https://opensource.com/life/16/8/how-construct-your-own-git-server-part-6"},{default:n(()=>[...s[6]||(s[6]=[i("閲讀 Seth Kenlon 的 Git 鈎子介紹",-1)])]),_:1}),s[10]||(s[10]=i("。",-1))]),s[39]||(s[39]=t("h3",{id:"_6、查看另一個分支的文件",tabindex:"-1"},[i("6、查看另一個分支的文件 "),t("a",{class:"header-anchor",href:"#_6、查看另一個分支的文件","aria-label":"Permalink to “6、查看另一個分支的文件”"},"​")],-1)),s[40]||(s[40]=t("p",null,"有時你想查看另一個分支的文件的內容。用一個簡單的 Git 命令就可以實現，而且不需要切換分支。",-1)),t("p",null,[s[12]||(s[12]=i("假設你有一個名為 ",-1)),e(a,{href:"http://README.md"},{default:n(()=>[...s[11]||(s[11]=[i("README.md",-1)])]),_:1}),s[13]||(s[13]=i(" 的文件，它在 ",-1)),s[14]||(s[14]=t("code",null,"main",-1)),s[15]||(s[15]=i(" 分支中，而你正在 ",-1)),s[16]||(s[16]=t("code",null,"dev",-1)),s[17]||(s[17]=i(" 分支上工作。",-1))]),s[41]||(s[41]=l(`<p>使用下面的 Git 命令，你可以在終端上完成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git show main:README.md</span></span></code></pre></div><p>一旦你執行了這個命令，你就可以在你的終端上查看文件的內容。</p><h3 id="_7、在-git-中搜索" tabindex="-1">7、在 Git 中搜索 <a class="header-anchor" href="#_7、在-git-中搜索" aria-label="Permalink to “7、在 Git 中搜索”">​</a></h3><p>只需一個簡單的命令，你就可以像專業人士一樣在 Git 中搜索。更棒的是，即使你不確定是在哪個提交或分支上做的修改，也可以在 Git 中搜索。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list --all | xargs git grep -F &#39;string&#39;</span></span></code></pre></div><p>例如，假設你想在你的版本庫中搜索 <code>font-size: 52 px;</code> 這個字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git rev-list –all | xargs git grep -F &#39;font-size: 52 px;&#39;</span></span>
<span class="line"><span>F3022…9e12:HtmlTemplate/style.css: font-size: 52 px;</span></span>
<span class="line"><span>E9211…8244:RR.Web/Content/style/style.css: font-size: 52 px;</span></span></code></pre></div><h3 id="試試這些技巧" tabindex="-1">試試這些技巧 <a class="header-anchor" href="#試試這些技巧" aria-label="Permalink to “試試這些技巧”">​</a></h3><p>希望這些高級技巧對你有用，提高你的工作效率，為你節省很多時間。</p>`,10)),t("p",null,[s[19]||(s[19]=i("你有喜歡的 ",-1)),e(a,{href:"https://acompiler.com/git-tips/"},{default:n(()=>[...s[18]||(s[18]=[i("Git 小技巧",-1)])]),_:1}),s[20]||(s[20]=i(" 嗎？在評論中分享吧。",-1))]),s[42]||(s[42]=t("hr",null,null,-1)),t("p",null,[s[22]||(s[22]=i("via: ",-1)),e(a,{href:"https://opensource.com/article/20/10/advanced-git-tips"},{default:n(()=>[...s[21]||(s[21]=[i("https://opensource.com/article/20/10/advanced-git-tips",-1)])]),_:1})]),t("p",null,[s[27]||(s[27]=i("作者：",-1)),e(a,{href:"https://opensource.com/users/acompiler"},{default:n(()=>[...s[23]||(s[23]=[i("Rajeev Bera",-1)])]),_:1}),s[28]||(s[28]=i(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[24]||(s[24]=[i("lujun9972",-1)])]),_:1}),s[29]||(s[29]=i(" 譯者：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[25]||(s[25]=[i("wxy",-1)])]),_:1}),s[30]||(s[30]=i(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[26]||(s[26]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[33]||(s[33]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[31]||(s[31]=[i("LCTT",-1)])]),_:1}),s[34]||(s[34]=i(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...s[32]||(s[32]=[i("Linux中國",-1)])]),_:1}),s[35]||(s[35]=i(" 榮譽推出",-1))])])}const x=p(g,[["render",h]]);export{C as __pageData,x as default};
